def maxOccurrences(s, maxLetters, minSize, maxSize):
    n = len(s)
    if minSize > n:
        return 0
    cnt = {}
    distinct = 0
    freq = {}
    best = 0
    for i, ch in enumerate(s):
        c = cnt.get(ch, 0)
        if c == 0:
            distinct += 1
        cnt[ch] = c + 1
        if i >= minSize:
            old = s[i - minSize]
            cnt[old] -= 1
            if cnt[old] == 0:
                distinct -= 1
        if i >= minSize - 1 and distinct <= maxLetters:
            t = s[i - minSize + 1:i + 1]
            freq[t] = freq.get(t, 0) + 1
            if freq[t] > best:
                best = freq[t]
    return best
